  "گفتگویی پیدا نشد.": ["No chats found.", "لم يتم العثور على محادثات.", "Sohbet bulunamadı.", "Чаты не найдены.", "No se encontraron chats.", "Aucune discussion trouvée.", "未找到对话。"],
  "هنوز گفتگویی نداری.": ["You have no chats yet.", "ليست لديك محادثات بعد.", "Henüz sohbetin yok.", "У вас пока нет чатов.", "Aún no tienes chats.", "Tu n'as pas encore de discussion.", "你还没有任何对话。"],
  "نام کاربری کسی را بالا جستجو کن و پیام بده.": ["Search for someone's username above and send a message.", "ابحث عن اسم مستخدم شخص في الأعلى وأرسل له رسالة.", "Yukarıdan birinin kullanıcı adını ara ve mesaj gönder.", "Найдите имя пользователя выше и напишите ему.", "Busca arriba el nombre de usuario de alguien y envíale un mensaje.", "Cherche un nom d'utilisateur ci-dessus et envoie un message.", "在上方搜索用户名并发送消息。"],
  "کاربران": ["Users", "المستخدمون", "Kullanıcılar", "Пользователи", "Usuarios", "Utilisateurs", "用户"],
  "در حال بارگذاری…": ["Loading…", "جارٍ التحميل…", "Yükleniyor…", "Загрузка…", "Cargando…", "Chargement…", "加载中…"],
  "عملیات انجام نشد.": ["The action failed.", "تعذّر تنفيذ العملية.", "İşlem yapılamadı.", "Не удалось выполнить действие.", "No se pudo completar la acción.", "L'action a échoué.", "操作失败。"],
  "چند نفر در حال نوشتن‌اند…": ["Several people are typing…", "عدة أشخاص يكتبون…", "Birkaç kişi yazıyor…", "Несколько человек печатают…", "Varias personas están escribiendo…", "Plusieurs personnes écrivent…", "多人正在输入…"],
  "{a} در حال نوشتن…": ["{a} is typing…", "{a} يكتب…", "{a} yazıyor…", "{a} печатает…", "{a} está escribiendo…", "{a} écrit…", "{a} 正在输入…"],
  "{a} و {b} در حال نوشتن…": ["{a} and {b} are typing…", "{a} و {b} يكتبان…", "{a} ve {b} yazıyor…", "{a} и {b} печатают…", "{a} y {b} están escribiendo…", "{a} et {b} écrivent…", "{a} 和 {b} 正在输入…"],
  "ویرایش پیام": ["Edit message", "تعديل الرسالة", "Mesajı düzenle", "Редактирование сообщения", "Editar mensaje", "Modifier le message", "编辑消息"],
  "پاسخ به {name}": ["Reply to {name}", "الرد على {name}", "{name} kişisine yanıt", "Ответ для {name}", "Responder a {name}", "Répondre à {name}", "回复 {name}"],
  "نشست تمام شد؛ دوباره وارد شو.": ["Your session has ended. Please log in again.", "انتهت الجلسة؛ سجّل الدخول مرة أخرى.", "Oturum sona erdi; tekrar giriş yap.", "Сеанс завершён; войдите снова.", "La sesión ha terminado; vuelve a iniciar sesión.", "La session a expiré ; reconnecte-toi.", "会话已结束，请重新登录。"],
  "پیام ارسال نشد؛ اینترنتت را بررسی کن و روی پیام بزن.": ["Message not sent. Check your internet and tap the message to retry.", "لم تُرسل الرسالة؛ تحقق من الإنترنت واضغط على الرسالة لإعادة المحاولة.", "Mesaj gönderilemedi; internetini kontrol et ve tekrar denemek için mesaja dokun.", "Сообщение не отправлено. Проверьте интернет и нажмите на сообщение, чтобы повторить.", "El mensaje no se envió. Revisa tu conexión y toca el mensaje para reintentar.", "Le message n'a pas été envoyé. Vérifie ta connexion et touche le message pour réessayer.", "消息未发送。请检查网络，然后点击消息重试。"],
  "پیام اصلی در بخش بارگذاری‌شده نیست.": ["The original message isn't in the loaded part of the chat.", "الرسالة الأصلية ليست ضمن الجزء المحمَّل من المحادثة.", "Asıl mesaj yüklenen bölümde değil.", "Исходного сообщения нет в загруженной части чата.", "El mensaje original no está en la parte cargada del chat.", "Le message d'origine n'est pas dans la partie chargée de la discussion.", "原消息不在已加载的部分中。"],
